const item = $input.first();
const confirmation = item.json.synthetic_confirmation ?? item.json['Synthetic data confirmation'];
if (!String(confirmation).includes('I confirm')) {
  throw new Error('Stage 8 accepts synthetic test data only.');
}
const binaryKeys = Object.keys(item.binary ?? {});
if (binaryKeys.length !== 1) {
  throw new Error('Upload exactly one JSON brief file.');
}
const binaryKey = binaryKeys[0];
const metadata = item.binary[binaryKey];
const filename = String(metadata.fileName ?? metadata.file_name ?? '');
if (!filename.toLowerCase().endsWith('.json')) {
  throw new Error('The uploaded brief must use a .json extension.');
}
const buffer = await helpers.getBinaryDataBuffer(0, binaryKey);
if (buffer.length > 65536) {
  throw new Error('The uploaded JSON brief exceeds the 64 KiB limit.');
}
let parsed;
try {
  parsed = JSON.parse(buffer.toString('utf8').replace(/^\uFEFF/, ''));
} catch {
  throw new Error('The uploaded brief is not valid JSON.');
}
if (!parsed || Array.isArray(parsed) || typeof parsed !== 'object') {
  throw new Error('The uploaded brief must be one JSON object.');
}
const allowed = ['schema_version', 'title', 'organization', 'decision_horizon', 'challenge', 'desired_outcomes', 'constraints', 'available_evidence', 'stakeholders', 'requested_by', 'supersedes_run_id'];
const unknown = Object.keys(parsed).filter((key) => !allowed.includes(key));
if (unknown.length) {
  throw new Error('Unknown brief fields: ' + unknown.sort().join(', '));
}
if (parsed.organization && typeof parsed.organization === 'object' && !Array.isArray(parsed.organization)) {
  const unknownOrganization = Object.keys(parsed.organization).filter((key) => !['name', 'type', 'context'].includes(key));
  if (unknownOrganization.length) {
    throw new Error('Unknown organization fields: ' + unknownOrganization.sort().join(', '));
  }
}
return [{ json: { ...parsed, schema_version: parsed.schema_version ?? '0.1', supersedes_run_id: parsed.supersedes_run_id ?? null } }];

const input = $json;
const value = (name, label) => input[name] ?? input[label] ?? '';
const lines = (name, label) => String(value(name, label)).split(/\r?\n/).map((item) => item.trim()).filter(Boolean);
const confirmation = value('synthetic_confirmation', 'Synthetic data confirmation');
if (!String(confirmation).includes('I confirm')) {
  throw new Error('Stage 8 accepts synthetic test data only.');
}
return [{
  json: {
    schema_version: '0.1',
    title: String(value('title', 'Strategy title')).trim(),
    organization: {
      name: String(value('organization_name', 'Organization name')).trim(),
      type: String(value('organization_type', 'Organization type')).trim(),
      context: String(value('organization_context', 'Organization context')).trim(),
    },
    decision_horizon: String(value('decision_horizon', 'Decision horizon')).trim(),
    challenge: String(value('challenge', 'Strategic challenge')).trim(),
    desired_outcomes: lines('desired_outcomes', 'Desired outcomes (one per line)'),
    constraints: lines('constraints', 'Constraints (one per line)'),
    available_evidence: lines('available_evidence', 'Available evidence (one per line)'),
    stakeholders: lines('stakeholders', 'Stakeholders (one per line)'),
    requested_by: String(value('requested_by', 'Requested by')).trim(),
    supersedes_run_id: null,
  },
}];

const input = $json;
const runId = input.run_id;
const qualityData = $('Generate Quality Report').item.json.data;
const filename = qualityData.quality_artifact?.filename ?? ('quality-report-' + runId + '.md');
const escapeHtml = (value) => String(value ?? '')
  .replaceAll('&', '&amp;')
  .replaceAll('<', '&lt;')
  .replaceAll('>', '&gt;')
  .replaceAll('\"', '&quot;')
  .replaceAll("'", '&#039;');
const recovery = [
  '<h2>Run and artifact locations</h2>',
  '<p><strong>Run ID:</strong> <code>' + escapeHtml(runId) + '</code></p>',
  '<p><strong>Advisory Markdown copy:</strong> <code>artifacts/quality-reports/' + escapeHtml(filename) + '</code></p>',
  '<p><strong>Status/recovery:</strong> <code>scripts/strategy-run-status.sh ' + escapeHtml(runId) + '</code></p>',
  '<p><em>The quality report is advisory. Only the decision below can approve or reject this strategy.</em></p>',
  '<hr>',
].join('');
return [{ json: { ...input, review_html: recovery + input.review_html } }];
